-- Thai Social Studies P1 official indicators.
-- Source: OBEC 2021 must-know/should-know table, printed pages 173-178.
-- This is the OBEC COVID-era implementation classification, not a replacement for the full core curriculum.
with seed(standard_code,objective_code,objective_name,sequence_no,is_required,source_indicator_code) as (
 values
('SO1.1','SO1.1-P1-01','บอกพุทธประวัติ หรือประวัติของศาสดาที่ตนนับถือโดยสังเขป',1,true,'ส ๑.๑ ป.๑/๑'),
('SO1.1','SO1.1-P1-02','ชื่นชมและบอกแบบอย่างการดำเนินชีวิตและข้อคิดจากประวัติสาวก ชาดก/เรื่องเล่า และศาสนิกชนตัวอย่างตามที่กำหนด',2,false,'ส ๑.๑ ป.๑/๒'),
('SO1.1','SO1.1-P1-03','บอกความหมาย ความสำคัญ และเคารพพระรัตนตรัย ปฏิบัติตามหลักธรรมโอวาท ๓ ในพระพุทธศาสนาหรือหลักธรรมของศาสนาที่ตนนับถือ ตามที่กำหนด',3,true,'ส ๑.๑ ป.๑/๓'),
('SO1.1','SO1.1-P1-04','เห็นคุณค่าและสวดมนต์ แผ่เมตตา มีสติที่เป็นพื้นฐานของสมาธิในพระพุทธศาสนาหรือการพัฒนาจิต ตามแนวทางของศาสนาที่ตนนับถือ ตามที่กำหนด',4,false,'ส ๑.๑ ป.๑/๔'),
('SO1.2','SO1.2-P1-01','บำเพ็ญประโยชน์ต่อวัด หรือศาสนสถานของศาสนาที่ตนนับถือ',1,false,'ส ๑.๒ ป.๑/๑'),
('SO1.2','SO1.2-P1-02','แสดงตนเป็นพุทธมามกะ หรือแสดงตนเป็นศาสนิกชนของศาสนาที่ตนนับถือ',2,false,'ส ๑.๒ ป.๑/๒'),
('SO1.2','SO1.2-P1-03','ปฏิบัติตนในศาสนพิธี พิธีกรรม และวันสำคัญทางศาสนา ตามที่กำหนดได้ถูกต้อง',3,true,'ส ๑.๒ ป.๑/๓'),
('SO2.1','SO2.1-P1-01','บอกประโยชน์และปฏิบัติตนเป็นสมาชิกที่ดีของครอบครัวและโรงเรียน',1,false,'ส ๒.๑ ป.๑/๑'),
('SO2.1','SO2.1-P1-02','ยกตัวอย่างความสามารถ และความดีของตนเอง ผู้อื่น และบอกผลจากการกระทำนั้น',2,true,'ส ๒.๑ ป.๑/๒'),
('SO2.2','SO2.2-P1-01','บอกโครงสร้าง บทบาทและหน้าที่ของสมาชิกในครอบครัวและโรงเรียน',1,false,'ส ๒.๒ ป.๑/๑'),
('SO2.2','SO2.2-P1-02','ระบุบทบาท สิทธิ หน้าที่ของตนเองในครอบครัวและโรงเรียน',2,true,'ส ๒.๒ ป.๑/๒'),
('SO2.2','SO2.2-P1-03','มีส่วนร่วมในการตัดสินใจและทำกิจกรรมในครอบครัวและโรงเรียนตามกระบวนการประชาธิปไตย',3,false,'ส ๒.๒ ป.๑/๓'),
('SO3.1','SO3.1-P1-01','ระบุสินค้า และบริการที่ใช้ประโยชน์ในชีวิตประจำวัน',1,false,'ส ๓.๑ ป.๑/๑'),
('SO3.1','SO3.1-P1-02','ยกตัวอย่างการใช้จ่ายเงินในชีวิตประจำวันที่ไม่เกินตัวและเห็นประโยชน์ของการออม',2,true,'ส ๓.๑ ป.๑/๒'),
('SO3.1','SO3.1-P1-03','ยกตัวอย่างการใช้ทรัพยากรในชีวิตประจำวันอย่างประหยัด',3,false,'ส ๓.๑ ป.๑/๓'),
('SO3.2','SO3.2-P1-01','อธิบายเหตุผลความจำเป็นที่คนต้องทำงานอย่างสุจริต',1,false,'ส ๓.๒ ป.๑/๑'),
('SO4.1','SO4.1-P1-01','บอกวัน เดือน ปี และการนับช่วงเวลาตามปฏิทินที่ใช้ในชีวิตประจำวัน',1,false,'ส ๔.๑ ป.๑/๑'),
('SO4.1','SO4.1-P1-02','เรียงลำดับเหตุการณ์ในชีวิตประจำวัน ตามวันเวลาที่เกิดขึ้น',2,false,'ส ๔.๑ ป.๑/๒'),
('SO4.1','SO4.1-P1-03','บอกประวัติความเป็นมาของตนเองและครอบครัวโดยสอบถามผู้เกี่ยวข้อง',3,false,'ส ๔.๑ ป.๑/๓'),
('SO4.2','SO4.2-P1-01','บอกความเปลี่ยนแปลงของสภาพแวดล้อม สิ่งของเครื่องใช้ หรือการดำเนินชีวิตของตนเองกับสมัยของพ่อแม่ ปู่ย่า ตายาย',1,false,'ส ๔.๒ ป.๑/๑'),
('SO4.2','SO4.2-P1-02','บอกเหตุการณ์ที่เกิดขึ้นในอดีตที่มีผลกระทบต่อตนเองในปัจจุบัน',2,false,'ส ๔.๒ ป.๑/๒'),
('SO4.3','SO4.3-P1-01','อธิบายความหมายและความสำคัญของสัญลักษณ์สำคัญของชาติไทยและปฏิบัติได้ถูกต้อง',1,true,'ส ๔.๓ ป.๑/๑'),
('SO4.3','SO4.3-P1-02','บอกสถานที่สำคัญซึ่งเป็นแหล่งวัฒนธรรมในชุมชน',2,false,'ส ๔.๓ ป.๑/๒'),
('SO4.3','SO4.3-P1-03','ระบุสิ่งที่ตนรักและภาคภูมิใจในท้องถิ่น',3,false,'ส ๔.๓ ป.๑/๓'),
('SO5.1','SO5.1-P1-01','จำแนกสิ่งแวดล้อมรอบตัวที่เกิดขึ้นเองตามธรรมชาติและที่มนุษย์สร้างขึ้น',1,false,'ส ๔.๑ ป.๑/๑ (รายการในตารางภูมิศาสตร์; จัดเข้ามาตรฐานภูมิศาสตร์ตามสาระ)'),
('SO5.1','SO5.1-P1-02','ระบุความสัมพันธ์ของตำแหน่ง ระยะ และทิศของสิ่งต่าง ๆ',2,true,'ส ๕.๑ ป.๑/๒'),
('SO5.1','SO5.1-P1-03','ใช้แผนผังแสดงตำแหน่งของสิ่งต่าง ๆ ในห้องเรียน',3,false,'ส ๕.๑ ป.๑/๓'),
('SO5.1','SO5.1-P1-04','สังเกตและบอกการเปลี่ยนแปลงของสภาพอากาศในรอบวัน',4,false,'ส ๕.๑ ป.๑/๔'),
('SO5.2','SO5.2-P1-01','บอกสิ่งแวดล้อมที่เกิดตามธรรมชาติที่ส่งผลต่อความเป็นอยู่ของมนุษย์',1,true,'ส ๕.๒ ป.๑/๑'),
('SO5.2','SO5.2-P1-02','สังเกตและเปรียบเทียบการเปลี่ยนแปลงของสิ่งแวดล้อมเพื่อการปฏิบัติตนอย่างเหมาะสม',2,true,'ส ๕.๒ ป.๑/๒'),
('SO5.2','SO5.2-P1-03','มีส่วนร่วมในการดูแลสิ่งแวดล้อมที่บ้านและห้องเรียน',3,true,'ส ๕.๒ ป.๑/๓')
)
insert into public.learning_objectives(topic_id,code,name,description,sequence_no,status)
select t.id,seed.objective_code,seed.objective_name,
 'OBEC indicator ' || seed.source_indicator_code || '; Prathom 1. Source: OBEC 2021 must-know/should-know Social Studies table, printed pages 173-178.',
 seed.sequence_no,'active'
from seed
join public.learning_topics t on t.code=seed.standard_code
join public.learning_skills sk on sk.id=t.skill_id
join public.learning_subjects s on s.id=sk.subject_id and s.code='SOCIAL-STUDIES'
on conflict(topic_id,code) do update set name=excluded.name,description=excluded.description,sequence_no=excluded.sequence_no,updated_at=now();

